"use client"

import { useState, useMemo } from "react"
import { ChevronLeft, ChevronRight } from "lucide-react"
import { buildPageArray } from "@/lib/page-builder"
import { IntroPage } from "@/components/IntroPage"
import { SectionDivider } from "@/components/SectionDivider"
import { RecipeCard } from "@/components/RecipeCard"

export default function RecipePage() {
  // Build the page array once using useMemo
  const pages = useMemo(() => buildPageArray(), [])

  const [currentPageIndex, setCurrentPageIndex] = useState(0)
  const [isAnimating, setIsAnimating] = useState(false)
  const currentPage = pages[currentPageIndex]
  const totalPages = pages.length

  const nextPage = () => {
    if (isAnimating) return
    setIsAnimating(true)
    setTimeout(() => {
      setCurrentPageIndex((prev) => (prev + 1) % totalPages)
      setTimeout(() => setIsAnimating(false), 50)
    }, 300)
  }

  const prevPage = () => {
    if (isAnimating) return
    setIsAnimating(true)
    setTimeout(() => {
      setCurrentPageIndex((prev) => (prev - 1 + totalPages) % totalPages)
      setTimeout(() => setIsAnimating(false), 50)
    }, 300)
  }

  const goToPage = (index: number) => {
    if (isAnimating || index === currentPageIndex) return
    setIsAnimating(true)
    setTimeout(() => {
      setCurrentPageIndex(index)
      setTimeout(() => setIsAnimating(false), 50)
    }, 300)
  }

  // Render the current page based on its type
  const renderPage = () => {
    switch (currentPage.type) {
      case 'intro':
        return <IntroPage />
      case 'section-divider':
        return (
          <SectionDivider
            categoryName={currentPage.categoryName}
            categoryId={currentPage.categoryId}
          />
        )
      case 'recipe':
        return (
          <RecipeCard
            recipe={currentPage.recipe}
            categoryNameUk={currentPage.categoryNameUk}
            categoryId={currentPage.categoryId}
          />
        )
      default:
        return <div>Unknown page type</div>
    }
  }

  return (
    <div className="min-h-screen bg-background relative">
      {/* Navigation Buttons */}
      <div className="fixed top-1/2 left-4 z-50 transform -translate-y-1/2">
        <button onClick={prevPage} className="recipe-nav-button group" aria-label="Попередня сторінка">
          <ChevronLeft className="w-6 h-6" />
          <span className="recipe-nav-tooltip">Попередня сторінка</span>
        </button>
      </div>

      <div className="fixed top-1/2 right-4 z-50 transform -translate-y-1/2">
        <button onClick={nextPage} className="recipe-nav-button group" aria-label="Наступна сторінка">
          <ChevronRight className="w-6 h-6" />
          <span className="recipe-nav-tooltip">Наступна сторінка</span>
        </button>
      </div>

      {/* Page Indicators - Enhanced for 67 pages */}
      <div className="fixed bottom-8 left-1/2 transform -translate-x-1/2 z-50">
        <div className="flex flex-col items-center gap-3">
          {/* Page counter */}
          <div className="px-4 py-2 bg-background/80 backdrop-blur-sm border border-border rounded-full">
            <span className="text-sm font-mono text-foreground">
              Сторінка {currentPageIndex + 1} / {totalPages}
            </span>
          </div>

          {/* Dot indicators - show subset around current page */}
          <div className="flex gap-2">
            {/* Show first page indicator */}
            {currentPageIndex > 3 && (
              <>
                <button
                  onClick={() => goToPage(0)}
                  className={`recipe-indicator ${currentPageIndex === 0 ? "active" : ""}`}
                  aria-label="Сторінка 1"
                />
                {currentPageIndex > 4 && (
                  <span className="text-muted-foreground text-xs self-center">...</span>
                )}
              </>
            )}

            {/* Show pages around current page */}
            {Array.from({ length: totalPages }, (_, index) => {
              // Show pages within range of current page
              const distance = Math.abs(index - currentPageIndex)
              if (distance <= 3 || index === 0 || index === totalPages - 1) {
                // Don't show first/last if already shown above
                if ((index === 0 && currentPageIndex > 3) || (index === totalPages - 1 && currentPageIndex < totalPages - 4)) {
                  return null
                }
                return (
                  <button
                    key={index}
                    onClick={() => goToPage(index)}
                    className={`recipe-indicator ${index === currentPageIndex ? "active" : ""}`}
                    aria-label={`Сторінка ${index + 1}`}
                  />
                )
              }
              return null
            })}

            {/* Show last page indicator */}
            {currentPageIndex < totalPages - 4 && (
              <>
                {currentPageIndex < totalPages - 5 && (
                  <span className="text-muted-foreground text-xs self-center">...</span>
                )}
                <button
                  onClick={() => goToPage(totalPages - 1)}
                  className={`recipe-indicator ${currentPageIndex === totalPages - 1 ? "active" : ""}`}
                  aria-label={`Сторінка ${totalPages}`}
                />
              </>
            )}
          </div>
        </div>
      </div>

      {/* Page Content */}
      <div className={`recipe-content ${isAnimating ? "fade-out" : "fade-in"}`}>
        {renderPage()}
      </div>
    </div>
  )
}

import { memo, useMemo } from 'react'
import Image from 'next/image'
import type { Recipe } from '@/types/recipe'
import { normalizeImagePath } from '@/lib/recipe-loader'

interface RecipeCardProps {
  recipe: Recipe
  categoryNameUk: string
  categoryId: string
}

// Helper interface for ingredient sections
interface IngredientSection {
  header?: string
  items: string[]
}

// Helper function to parse ingredient sections
function parseIngredientSections(ingredients: string[]): IngredientSection[] {
  const sections: IngredientSection[] = []
  let currentSection: IngredientSection = { items: [] }

  for (const ingredient of ingredients) {
    // Check if this is a section header (ends with ":")
    if (ingredient.trim().endsWith(':')) {
      // Save the current section if it has items
      if (currentSection.items.length > 0) {
        sections.push(currentSection)
      }
      // Start a new section with this header
      currentSection = { header: ingredient, items: [] }
    } else {
      // Add to current section
      currentSection.items.push(ingredient)
    }
  }

  // Add the final section if it has items
  if (currentSection.items.length > 0) {
    sections.push(currentSection)
  }

  return sections
}

// Helper function to get recipe stats
function getRecipeStats(recipe: Recipe) {
  const ingredientCount = recipe.ingredients.length
  const hasInstructions = recipe.how_to_cook.length > 0

  return {
    ingredientCount,
    hasInstructions,
    ingredientLabel: `${ingredientCount} ${ingredientCount === 1 ? 'інгредієнт' : ingredientCount < 5 ? 'інгредієнти' : 'інгредієнтів'}`,
    instructionLabel: hasInstructions ? 'Покрокова інструкція' : 'Швидкий рецепт'
  }
}

function RecipeCardComponent({ recipe, categoryNameUk, categoryId }: RecipeCardProps) {
  const imagePath = normalizeImagePath(recipe.image_path)

  // Determine category display name and color
  const getCategoryInfo = () => {
    switch (categoryId) {
      case 'breakfast':
        return { name: 'Сніданки', class: 'category-daily' }
      case 'lunch_dinner':
        return { name: 'Обід/Вечеря', class: 'category-occasional' }
      case 'desserts':
        return { name: 'Десерти', class: 'category-special' }
      default:
        return { name: categoryNameUk, class: 'category-daily' }
    }
  }

  const categoryInfo = getCategoryInfo()

  // Parse ingredient sections (memoized for performance)
  const ingredientSections = useMemo(() => parseIngredientSections(recipe.ingredients), [recipe.ingredients])

  // Get recipe stats
  const stats = getRecipeStats(recipe)

  return (
    <>
      {/* Hero Section */}
      <div className="recipe-hero min-h-screen flex flex-col justify-center items-center px-8 py-16">
        <div className="max-w-4xl mx-auto text-center">
          <div className="mb-8">
            <p className="text-sm tracking-widest text-muted-foreground uppercase font-mono">
              • {categoryInfo.name} •
            </p>
          </div>

          <div className="mb-12">
            <h1 className="text-5xl md:text-6xl font-serif text-foreground mb-4 text-balance">
              {recipe.title}
            </h1>
            <div className="recipe-divider w-24 mx-auto mb-6"></div>

            {/* Quick Stats Badges */}
            <div className="flex flex-wrap items-center justify-center gap-3 mt-6">
              <div className="recipe-stat-badge">
                <span className="stat-icon">🥘</span>
                <span>{stats.ingredientLabel}</span>
              </div>
              <div className={`recipe-stat-badge ${stats.hasInstructions ? 'stat-badge-success' : 'stat-badge-info'}`}>
                <span className="stat-icon">{stats.hasInstructions ? '📖' : '⚡'}</span>
                <span>{stats.instructionLabel}</span>
              </div>
            </div>
          </div>

          <div className="mb-12">
            <div className="relative w-full max-w-2xl mx-auto h-96 rounded-lg overflow-hidden shadow-2xl">
              <Image
                src={imagePath}
                alt={recipe.title}
                fill
                className="object-cover"
                sizes="(max-width: 768px) 100vw, 896px"
                loading="lazy"
                quality={85}
              />
            </div>
          </div>

          <div className="mt-8">
            <div className="category-indicator">
              <div className={`category-dot ${categoryInfo.class}`}></div>
              <span>{categoryInfo.name}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Details Section */}
      <div className="bg-background px-8 py-16">
        <div className="max-w-6xl mx-auto">
          <div className="text-center mb-16">
            <h3 className="text-4xl font-serif text-foreground mb-4">Рецепт приготування</h3>
            <div className="recipe-divider w-16 mx-auto"></div>
          </div>

          <div className="grid lg:grid-cols-2 gap-16">
            {/* Left Column - Ingredients */}
            <div>
              <section>
                <h4 className="text-2xl font-serif text-foreground mb-8">Інгредієнти</h4>

                {recipe.ingredients.length > 0 ? (
                  <div className="space-y-6">
                    {ingredientSections.map((section, sectionIndex) => {
                      // Calculate starting number for this section
                      const startNumber = ingredientSections
                        .slice(0, sectionIndex)
                        .reduce((sum, s) => sum + s.items.length, 0) + 1

                      return (
                        <div key={sectionIndex}>
                          {/* Section Header */}
                          {section.header && (
                            <div className="ingredient-section-header mb-3">
                              {section.header}
                            </div>
                          )}

                          {/* Section Items */}
                          <div className="space-y-3">
                            {section.items.map((ingredient, itemIndex) => (
                              <div
                                key={itemIndex}
                                className="flex items-start py-3 border-b border-border"
                              >
                                <span className="flex-shrink-0 inline-flex items-center justify-center w-6 h-6 rounded-full bg-muted text-muted-foreground text-xs mr-3 mt-0.5">
                                  {startNumber + itemIndex}
                                </span>
                                <span className="text-foreground flex-1">{ingredient}</span>
                              </div>
                            ))}
                          </div>
                        </div>
                      )
                    })}
                  </div>
                ) : (
                  <p className="text-muted-foreground italic">Інгредієнти не вказані</p>
                )}
              </section>
            </div>

            {/* Right Column - Instructions */}
            <div>
              <section>
                <h4 className="text-2xl font-serif text-foreground mb-8">Спосіб приготування</h4>

                {recipe.how_to_cook.length > 0 ? (
                  <div className="space-y-6">
                    {recipe.how_to_cook.map((instruction, index) => (
                      <div key={index} className="flex gap-4">
                        <div className="flex-shrink-0">
                          <span className="inline-flex items-center justify-center w-8 h-8 rounded-full bg-accent text-accent-foreground font-mono text-sm">
                            {index + 1}
                          </span>
                        </div>
                        <p className="text-muted-foreground leading-relaxed pt-1">{instruction}</p>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="empty-instructions-message">
                    <div className="empty-message-icon">⚡</div>
                    <h5 className="empty-message-title">Швидкий рецепт</h5>
                    <p className="empty-message-text">
                      Це швидкий рецепт без покрокової інструкції. Насолоджуйтесь творчим процесом приготування!
                    </p>
                  </div>
                )}
              </section>
            </div>
          </div>
        </div>
      </div>
    </>
  )
}

// Memoize the component to prevent unnecessary re-renders
export const RecipeCard = memo(RecipeCardComponent)

// Recipe data structure types based on recipes.json

export interface Recipe {
  id: number
  title: string
  ingredients: string[]
  how_to_cook: string[]
  image_path: string
}

export interface Category {
  id: string
  name_en: string
  name_uk: string
  start_marker: string
  end_marker: string | null
  recipes: Recipe[]
}

export interface RecipeData {
  categories: Category[]
}

// Page types for the recipe book
export type PageType = 'intro' | 'recipe' | 'section-divider'

export interface IntroPageData {
  type: 'intro'
}

export interface RecipePageData {
  type: 'recipe'
  recipe: Recipe
  categoryId: string
  categoryNameUk: string
}

export interface SectionDividerPageData {
  type: 'section-divider'
  categoryName: string
  categoryId: string
}

export type Page = IntroPageData | RecipePageData | SectionDividerPageData

@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.577 0.245 27.325);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --radius: 0.625rem;
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);
}

@theme inline {
  /* Typography */
  --font-sans: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol",
    "Noto Color Emoji";
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Consolas, "Liberation Mono", Menlo, monospace;

  /* Colors - Elegant khaki base with subtle cherry red accents */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-muted: oklch(0.97 0 0);
  --color-muted-foreground: oklch(0.556 0 0);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  /* Primary khaki tones */
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);

  /* Subtle cherry red accent */
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);

  /* Secondary warm tones */
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);

  /* Destructive (keeping cherry red theme) */
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);

  /* Card and popover */
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  /* Border radius */
  --radius: var(--radius);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  /* Sidebar */
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

/* Custom recipe layout styles */
.recipe-hero {
  background: linear-gradient(135deg, var(--color-muted) 0%, var(--color-background) 100%);
}

.recipe-accent {
  color: var(--color-accent);
}

.recipe-divider {
  background: linear-gradient(90deg, var(--color-primary) 0%, transparent 100%);
  height: 2px;
}

/* Adding elegant category indicator styles */
.category-indicator {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1.5rem;
  border-radius: 2rem;
  background: oklch(0.98 0 0);
  border: 1px solid oklch(0.92 0 0);
  font-weight: 500;
  font-size: 0.875rem;
  letter-spacing: 0.025em;
  transition: all 0.2s ease;
}

.category-indicator:hover {
  background: oklch(0.96 0 0);
  border-color: oklch(0.88 0 0);
}

.category-dot {
  width: 0.75rem;
  height: 0.75rem;
  border-radius: 50%;
  flex-shrink: 0;
}

.category-daily {
  background: oklch(0.6 0.15 145);
  box-shadow: 0 0 0 2px oklch(0.6 0.15 145 / 0.2);
}

.category-occasional {
  background: oklch(0.65 0.18 85);
  box-shadow: 0 0 0 2px oklch(0.65 0.18 85 / 0.2);
}

.category-special {
  background: oklch(0.55 0.2 25);
  box-shadow: 0 0 0 2px oklch(0.55 0.2 25 / 0.2);
}

.nutrition-bar {
  background: oklch(0.95 0 0);
  border-radius: 8px;
  overflow: hidden;
  height: 8px;
  width: 100%;
}

.nutrition-segment {
  height: 8px;
  display: block;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.nutrition-protein {
  background: oklch(0.45 0.15 120);
}

.nutrition-carbs {
  background: oklch(0.55 0.2 60);
}

.nutrition-fats {
  background: oklch(0.35 0.1 30);
}

.nutrition-fiber {
  background: oklch(0.6 0.18 150);
}

/* Adding elegant recipe navigation styles */
.recipe-nav-button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 3.5rem;
  height: 3.5rem;
  border-radius: 50%;
  background: oklch(0.98 0 0);
  border: 1px solid oklch(0.92 0 0);
  color: var(--color-foreground);
  transition: all 0.3s ease;
  backdrop-filter: blur(8px);
  box-shadow: 0 4px 12px oklch(0 0 0 / 0.1);
  position: relative;
}

.recipe-nav-button:hover {
  background: oklch(0.95 0 0);
  border-color: var(--color-primary);
  transform: scale(1.05);
  box-shadow: 0 6px 20px oklch(0 0 0 / 0.15);
}

.recipe-nav-button:active {
  transform: scale(0.95);
}

.recipe-nav-tooltip {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: var(--color-foreground);
  color: var(--color-background);
  padding: 0.5rem 0.75rem;
  border-radius: 0.5rem;
  font-size: 0.75rem;
  font-weight: 500;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: all 0.2s ease;
  z-index: 10;
}

.recipe-nav-button:hover .recipe-nav-tooltip {
  opacity: 1;
}

.recipe-nav-button:first-child .recipe-nav-tooltip {
  right: calc(100% + 0.75rem);
}

.recipe-nav-button:last-child .recipe-nav-tooltip {
  left: calc(100% + 0.75rem);
}

.recipe-indicator {
  width: 0.75rem;
  height: 0.75rem;
  border-radius: 50%;
  background: oklch(0.85 0 0);
  border: 2px solid oklch(0.92 0 0);
  transition: all 0.3s ease;
  cursor: pointer;
}

.recipe-indicator:hover {
  background: oklch(0.75 0 0);
  transform: scale(1.1);
}

.recipe-indicator.active {
  background: var(--color-primary);
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px oklch(0.205 0 0 / 0.2);
}

/* Adding elegant fade animations for recipe transitions */
.recipe-content {
  transition: opacity 0.3s ease-in-out, transform 0.3s ease-in-out;
  opacity: 1;
  transform: translateY(0);
}

.recipe-content.fade-out {
  opacity: 0;
  transform: translateY(-10px);
}

.recipe-content.fade-in {
  opacity: 1;
  transform: translateY(0);
}

/* Recipe stat badges for quick-scan information */
.recipe-stat-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: 1.5rem;
  background: oklch(0.98 0 0);
  border: 1px solid oklch(0.92 0 0);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-foreground);
  transition: all 0.2s ease;
}

.recipe-stat-badge .stat-icon {
  font-size: 1rem;
  line-height: 1;
}

.recipe-stat-badge:hover {
  background: oklch(0.96 0 0);
  transform: translateY(-1px);
  box-shadow: 0 2px 8px oklch(0 0 0 / 0.1);
}

.stat-badge-success {
  background: oklch(0.95 0.05 145);
  border-color: oklch(0.6 0.15 145);
  color: oklch(0.3 0.1 145);
}

.stat-badge-info {
  background: oklch(0.95 0.05 240);
  border-color: oklch(0.6 0.15 240);
  color: oklch(0.3 0.1 240);
}

/* Ingredient section headers */
.ingredient-section-header {
  font-size: 1.125rem;
  font-weight: 600;
  font-family: var(--font-serif);
  color: var(--color-foreground);
  padding: 0.75rem 1rem;
  background: oklch(0.98 0 0);
